internal static partial class WideCorpus
{
    private static WideModule[] SystemsModules() => [Quill(), Council(), Switchyard()];

    private static WideModule Quill() => new("Quill", "The document service projects saved edits, revision provenance and export metadata. Coordinates and counts are nonnegative unless an operation documents a signed value. Flags are 0 or 1. Inputs keep intermediates within signed 64-bit bounds.",
    [
        Fault("RevisionOrigin", "long document, long epoch, long proofDocument, long proofEpoch, long proofOrigin, long baseDocument, long baseEpoch, long baseOrigin",
            "Return the origin of an exact proof for this document and epoch. Without a matching proof, use the supplied base if it belongs to this document and its epoch is at or before the requested epoch. Return -1 if no source qualifies. Zero is an assigned origin.",
            "if (proofEpoch == epoch) return proofDocument == document ? proofOrigin : -1;\nreturn baseDocument == document && baseEpoch <= epoch ? baseOrigin : -1;",
            "if (proofDocument == document && proofEpoch == epoch) return proofOrigin;\nreturn baseDocument == document && baseEpoch <= epoch ? baseOrigin : -1;",
            [7, 4, 7, 4, 41, 7, 3, 19], 41, [7, 4, 8, 4, 41, 7, 3, 0], 0),
        Fault("ActiveReplacementCount", "long firstId, long firstRevision, long firstState, long secondId, long secondRevision, long secondState",
            "Count pending replacement requests. State 1 is pending, 0 is withdrawn and 2 is applied. For one ID, only the latest revision counts, with the second row winning a revision tie. The state of a superseded row has no effect.",
            "var changes = new[] { (Id: firstId, Revision: firstRevision, State: firstState), (Id: secondId, Revision: secondRevision, State: secondState) };\nreturn changes.Where(row => row.State == 1).GroupBy(row => row.Id).Count();",
            "var changes = new[] { (Id: firstId, Revision: firstRevision, State: firstState), (Id: secondId, Revision: secondRevision, State: secondState) };\nreturn changes.GroupBy(row => row.Id).Count(history => history.OrderBy(row => row.Revision).Last().State == 1);",
            [3, 7, 1, 8, 6, 0], 1, [3, 7, 1, 3, 8, 0], 0),
        Fault("CountHardBreaks", "long leftBreaks, long rightBreaks, long insertBreaks, long insertLength, long leftTail, long insertHead, long insertTail, long rightHead",
            "Return the hard break count after inserting a fragment between the left and right pieces. Each supplied count already treats a CR-LF pair within its own piece as one break. Edge codes are 0 for an empty piece, 1 for CR, 2 for LF and 3 for any other character. An empty insert joins the outside edges directly. Each newly adjacent CR-LF pair reduces the sum by one.",
            "var total = leftBreaks + rightBreaks + insertBreaks;\nif (insertLength == 0) return total - (leftTail == 1 && rightHead == 2 ? 1 : 0);\nvar pairedLeft = leftTail == 1 && insertHead == 2;\nvar pairedRight = insertTail == 1 && rightHead == 2;\nreturn total - (pairedLeft || pairedRight ? 1 : 0);",
            "var total = leftBreaks + rightBreaks + insertBreaks;\nif (insertLength == 0) return total - (leftTail == 1 && rightHead == 2 ? 1 : 0);\nvar pairedLeft = leftTail == 1 && insertHead == 2;\nvar pairedRight = insertTail == 1 && rightHead == 2;\nreturn total - (pairedLeft ? 1 : 0) - (pairedRight ? 1 : 0);",
            [3, 2, 1, 1, 1, 2, 2, 3], 5, [3, 2, 2, 2, 1, 2, 1, 2], 5),
        Fault("CountSharedExcerpt", "long start, long end, long firstStart, long firstEnd, long secondStart, long secondEnd",
            "Count characters in the excerpt whose positions belong to neither suppression interval. All three ranges are ordered and half-open. Suppression intervals may extend beyond either end of the excerpt.",
            "var first = Overlap(start, end, firstStart, firstEnd);\nvar second = Overlap(start, end, secondStart, secondEnd);\nvar shared = Overlap(firstStart, firstEnd, secondStart, secondEnd);\nreturn end - start - first - second + shared;\n\nstatic long Overlap(long a, long b, long c, long d) => Math.Max(0, Math.Min(b, d) - Math.Max(a, c));",
            "var first = Overlap(start, end, firstStart, firstEnd);\nvar second = Overlap(start, end, secondStart, secondEnd);\nvar shared = Overlap(start, end, Math.Max(firstStart, secondStart), Math.Min(firstEnd, secondEnd));\nreturn end - start - first - second + shared;\n\nstatic long Overlap(long a, long b, long c, long d) => Math.Max(0, Math.Min(b, d) - Math.Max(a, c));",
            [10, 30, 13, 17, 19, 22], 13, [10, 20, 0, 14, 2, 12], 6),
        Fault("RevisionDistance", "long oldEpoch, long oldSequence, long newEpoch, long newSequence, long epochSize",
            "Count revision steps between two chronologically ordered checkpoints in the same document. EpochSize is positive and gives the number of slots in each epoch, numbered from zero. After the final slot, the next step reaches slot zero of the following epoch.",
            "var complete = (newEpoch - oldEpoch) * epochSize;\nreturn complete + Math.Abs(newSequence - oldSequence);",
            "var complete = (newEpoch - oldEpoch) * epochSize;\nreturn complete + newSequence - oldSequence;",
            [8, 3, 8, 8, 16], 5, [8, 13, 9, 2, 16], 5),
        Fault("FormatMarkers", "long markers, long patch, long writable, long offset",
            "Replace the current marker bits in the writable mask with the patch, preserving current bits everywhere else. The patch uses fragment-local coordinates and needs a left shift by offset to line up with document coordinates. Masks are 16-bit unsigned values and offset is 0 through 15. Patch zeroes clear writable markers.",
            "var replacement = (patch & writable) << (int)offset;\nreturn (markers & ~writable) | replacement;",
            "var replacement = (patch << (int)offset) & writable;\nreturn (markers & ~writable) | replacement;",
            [10, 5, 6, 0], 12, [16, 3, 12, 2], 28),
        Fault("RestoredExcerptBytes", "long rawBytes, long escapePairs, long header, long budget",
            "Unescaping an excerpt replaces each disjoint two-byte escape pair with one byte. The export includes an unescaped excerpt and its header only when both fit in budget. Return their combined byte count or -1 if they cannot fit.",
            "var staged = rawBytes + header;\nif (staged > budget) return -1;\nreturn staged - escapePairs;",
            "var exported = rawBytes - escapePairs + header;\nreturn exported > budget ? -1 : exported;",
            [12, 2, 2, 20], 12, [12, 3, 2, 11], 11),
        Fault("HighlightRank", "long caret, long first, long second, long hiddenStart, long hiddenEnd, long tieWinner",
            "Return the closer highlight, 1 for first and 2 for second, using visible character distance from the caret. The half-open hidden span has no width for this distance. The two highlights and the caret may be on either side of or inside this span. TieWinner is 1 or 2.",
            "var rawFirst = Math.Abs(caret - first);\nvar rawSecond = Math.Abs(caret - second);\nif (rawFirst != rawSecond) return rawFirst < rawSecond ? 1 : 2;\nvar before = Distance(first);\nvar after = Distance(second);\nreturn before == after ? tieWinner : before < after ? 1 : 2;\n\nlong Distance(long position)\n{\n    var low = Math.Min(caret, position);\n    var high = Math.Max(caret, position);\n    return high - low - Math.Max(0, Math.Min(high, hiddenEnd) - Math.Max(low, hiddenStart));\n}",
            "var before = Distance(first);\nvar after = Distance(second);\nreturn before == after ? tieWinner : before < after ? 1 : 2;\n\nlong Distance(long position)\n{\n    var low = Math.Min(caret, position);\n    var high = Math.Max(caret, position);\n    return high - low - Math.Max(0, Math.Min(high, hiddenEnd) - Math.Max(low, hiddenStart));\n}",
            [10, 5, 20, 1, 4, 2], 1, [10, 3, 14, 4, 8, 2], 1),
        Fault("TranslateCaret", "long caret, long start, long removed, long inserted, long afterInserted",
            "Translate a caret through an edit that replaces the half-open range beginning at start and spanning removed characters. A caret strictly before the edit stays fixed. A caret at start or inside the removed characters maps to the start or end of the inserted text according to the afterInserted flag. A caret at the trailing edge of a nonempty removal follows the surviving suffix, as does any caret beyond the edit.",
            "if (caret < start) return caret;\nvar end = start + removed;\nif (caret > end) return caret - removed + inserted;\nreturn start + (afterInserted == 1 ? inserted : 0);",
            "if (caret < start) return caret;\nvar end = start + removed;\nif (caret >= end && caret != start) return caret - removed + inserted;\nreturn start + (afterInserted == 1 ? inserted : 0);",
            [19, 10, 3, 2, 0], 18, [13, 10, 3, 2, 0], 12),
        Fault("RetainedEditCredit", "long firstCount, long secondCount, long undoneCount, long firstWeight, long secondWeight, long undoWeight",
            "Compute credit from two contribution counts and an undo deduction. Weights are whole percentages from 0 to 100. Add and deduct the exact weighted counts, then floor the total after clamping negative credit to zero.",
            "var earned = firstCount * firstWeight / 100 + secondCount * secondWeight / 100;\nvar deduction = undoneCount * undoWeight / 100;\nreturn Math.Max(0, earned - deduction);",
            "var earned = firstCount * firstWeight + secondCount * secondWeight;\nvar deduction = undoneCount * undoWeight;\nreturn Math.Max(0, earned - deduction) / 100;",
            [4, 6, 1, 50, 50, 100], 4, [5, 3, 1, 55, 65, 70], 4),
        Valid("PrintablePages", "long lines, long frontMatter, long pageHeight",
            "The document body follows its front matter in the same page flow. Return the minimum number of pages to fit both, with pageHeight positive and an empty export occupying zero pages.",
            "var height = lines + frontMatter;\nreturn height / pageHeight + (height % pageHeight == 0 ? 0 : 1);", [18, 3, 10], 3),
        Valid("ExportName", "long chosenName, long fallbackName, long hasChosen",
            "Use the chosen export name ID when present, including an explicit zero. Otherwise return the fallback name ID.",
            "return hasChosen == 1 ? chosenName : fallbackName;", [0, 7, 1], 0)
    ]);

    private static WideModule Council() => new("Council", "The editorial review queue computes display badges, review assignments and consultation limits. Numeric IDs, counts, epochs and times are nonnegative unless a rule specifies a sentinel. Flags are 0 or 1. Inputs keep intermediates within signed 64-bit bounds.",
    [
        Fault("CountActiveReviewers", "long firstPerson, long firstStart, long firstEnd, long secondPerson, long secondStart, long secondEnd, long now",
            "Count distinct reviewers with an active assignment at now. Each ordered assignment window includes its start and excludes its end. The two assignments are independent even if they name the same reviewer.",
            "var firstActive = now >= firstStart && now < firstEnd;\nvar secondActive = now >= secondStart && now < secondEnd;\nif (firstPerson == secondPerson) return secondActive ? 1 : 0;\nreturn (firstActive ? 1 : 0) + (secondActive ? 1 : 0);",
            "var firstActive = now >= firstStart && now < firstEnd;\nvar secondActive = now >= secondStart && now < secondEnd;\nif (firstPerson == secondPerson) return firstActive || secondActive ? 1 : 0;\nreturn (firstActive ? 1 : 0) + (secondActive ? 1 : 0);",
            [3, 5, 10, 7, 6, 12, 8], 2, [3, 5, 10, 3, 9, 12, 8], 1),
        Fault("DisplayBadge", "long epoch, long localEpoch, long localState, long inheritedEpoch, long inheritedState",
            "Return 1 when an editorial badge should be visible. States are 0 for unset, 1 for explicitly hidden and 2 for visible. Discard states from any other epoch. A current local state overrides the inherited state when locally set.",
            "var local = localEpoch == epoch ? localState : 0;\nvar inherited = inheritedEpoch == epoch ? inheritedState : 0;\nreturn local == 2 || inherited == 2 ? 1 : 0;",
            "var local = localEpoch == epoch ? localState : 0;\nvar inherited = inheritedEpoch == epoch ? inheritedState : 0;\nreturn (local == 0 ? inherited : local) == 2 ? 1 : 0;",
            [4, 4, 2, 4, 0], 1, [4, 4, 1, 4, 2], 0),
        Fault("EffectiveQuorum", "long team, long partner, long overlap, long minimum, long outsideMinimum",
            "Return 1 when the distinct votes reach minimum and votes from outside the internal team reach outsideMinimum. Team and partner are sizes of voting sets. Overlap counts voters belonging to both groups. A dual member is an internal voter.",
            "var distinctVotes = team + partner - overlap;\nreturn distinctVotes >= minimum && partner >= outsideMinimum ? 1 : 0;",
            "var distinctVotes = team + partner - overlap;\nvar outsideVotes = partner - overlap;\nreturn distinctVotes >= minimum && outsideVotes >= outsideMinimum ? 1 : 0;",
            [4, 3, 0, 6, 2], 1, [4, 3, 2, 5, 2], 0),
        Fault("ReferralDegree", "long origin, long first, long second, long third, long destination",
            "Return the number of distinct intermediaries in an ordered referral record. The first, second and third slots may include repeated actors or either endpoint. The origin and destination are distinct and count only as endpoints wherever listed.",
            "return new[] { first, second, third }.Where(person => person != origin).Distinct().Count();",
            "return new[] { first, second, third }.Where(person => person != origin && person != destination).Distinct().Count();",
            [2, 4, 4, 5, 8], 2, [2, 4, 8, 5, 8], 2),
        Fault("CooldownElapsed", "long grantTime, long now, long pauseStart, long pauseEnd, long requiredActive",
            "Return 1 if the wait from grantTime to now has accumulated at least requiredActive minutes of active time. The ordered pause interval does not count toward the wait. Pause times may precede the grant or extend beyond now. Now is at or after grantTime.",
            "var paused = Math.Max(0, Math.Min(now, pauseEnd) - pauseStart);\nreturn now - grantTime - paused >= requiredActive ? 1 : 0;",
            "var paused = Math.Max(0, Math.Min(now, pauseEnd) - Math.Max(grantTime, pauseStart));\nreturn now - grantTime - paused >= requiredActive ? 1 : 0;",
            [10, 30, 13, 15, 18], 1, [10, 30, 5, 15, 15], 1),
        Fault("PropagateAllowance", "long requested, long templateCap, long localCap, long localEpoch, long currentEpoch",
            "Return the requested consultation allowance limited by each applicable cap. The template applies across epochs. The local cap applies only in its own epoch. A cap of -1 is unset and a cap of zero specifies an allowance of zero.",
            "var available = templateCap > 0 ? Math.Min(requested, templateCap) : requested;\nreturn localEpoch == currentEpoch && localCap > 0 ? Math.Min(localCap, available) : available;",
            "var available = templateCap >= 0 ? Math.Min(requested, templateCap) : requested;\nreturn localEpoch == currentEpoch && localCap >= 0 ? Math.Min(localCap, available) : available;",
            [15, 7, -1, 4, 4], 7, [15, 0, 6, 4, 4], 0),
        Fault("RemainingEscalations", "long limit, long currentEpoch, long snapshotEpoch, long opened, long reversed, long reserved",
            "Report unused escalation capacity. Opened and reversed describe the same snapshot, with reversed a subset of opened. Their net reduces capacity only in the current epoch. Reserved describes separate current reservations that always reduce capacity. Return zero when capacity is exhausted.",
            "var attempts = snapshotEpoch == currentEpoch ? opened : 0;\nreturn Math.Max(0, limit - attempts + reversed - reserved);",
            "var attempts = snapshotEpoch == currentEpoch ? opened - reversed : 0;\nreturn Math.Max(0, limit - attempts - reserved);",
            [10, 3, 3, 5, 2, 1], 6, [10, 3, 2, 5, 2, 4], 6),
        Fault("HighlightReviewWarning", "long active, long risk, long exitRisk, long enterRisk, long streak, long requiredStreak",
            "Update the review warning to 0 or 1. With a currently active warning, clear it only after a streak of at least requiredStreak observations at or below exitRisk. With an inactive warning, activate it after a streak of at least requiredStreak observations at or above enterRisk. The supplied streak ends at the current observation and measures the applicable threshold, including equality. ExitRisk is below enterRisk.",
            "if (streak < requiredStreak) return active;\nif (active == 1) return risk < exitRisk ? 0 : 1;\nreturn risk >= enterRisk ? 1 : 0;",
            "if (streak < requiredStreak) return active;\nif (active == 1) return risk <= exitRisk ? 0 : 1;\nreturn risk >= enterRisk ? 1 : 0;",
            [1, 2, 4, 7, 1, 2], 1, [1, 4, 4, 7, 2, 2], 0),
        Fault("TrustSampleAge", "long now, long observed, long received, long maximumSkew",
            "The editorial activity display reports age from the observed time. A receipt at or before now establishes the latest possible time of the activity. If observed exceeds received by at most maximumSkew, use received as the time. If it exceeds received by more, return -1. Otherwise use observed.",
            "if (observed > now && observed - received > maximumSkew) return -1;\nreturn now - Math.Min(observed, now);",
            "if (observed > received && observed - received > maximumSkew) return -1;\nreturn now - Math.Min(observed, received);",
            [30, 18, 20, 3], 12, [30, 24, 20, 3], -1),
        Fault("ReviewWindowMinutes", "long start, long end, long day, long openStart, long openLength",
            "Return minutes of overlap between a recurring review window and today's availability. The review window begins at start and ends before end, wrapping through midnight when end is smaller than start. Equal endpoints give an empty review window. Day is positive, start and end are below day, and the availability interval starts at openStart and does not wrap.",
            "var openEnd = openStart + openLength;\nvar beforeMidnight = end < start ? day : end;\nreturn Math.Max(0, Math.Min(beforeMidnight, openEnd) - Math.Max(start, openStart));",
            "var openEnd = openStart + openLength;\nvar beforeMidnight = end < start ? day : end;\nvar overlap = Math.Max(0, Math.Min(beforeMidnight, openEnd) - Math.Max(start, openStart));\nif (end < start) overlap += Math.Max(0, Math.Min(end, openEnd) - openStart);\nreturn overlap;",
            [3, 12, 24, 4, 3], 3, [20, 5, 24, 1, 6], 4),
        Valid("ReviewCapacity", "long reviewers, long ticketsPerReviewer, long pending",
            "Return how many more review tickets can be accepted if each reviewer can handle ticketsPerReviewer and pending tickets already use capacity. Capacity has a floor of zero.",
            "return Math.Max(0, reviewers * ticketsPerReviewer - pending);", [3, 2, 6], 0),
        Valid("DisplayedPriority", "long proposed, long queueDefault, long submitted, long maximum",
            "Return the submitted priority when submitted is set and the queue default otherwise. In either case maximum caps the displayed priority. An explicit proposed priority of zero is valid.",
            "var chosen = submitted == 1 ? proposed : queueDefault;\nreturn Math.Min(chosen, maximum);", [0, 5, 1, 3], 0)
    ]);

    private static WideModule Switchyard() => new("Switchyard", "The telemetry reader interprets packet metadata and emits aligned measurements. Counts, offsets and masks are nonnegative unless a rule allows signed values. Flags are 0 or 1. Inputs keep intermediates within signed 64-bit bounds.",
    [
        Fault("DeltaForSession", "long previousGeneration, long nextGeneration, long previousCount, long nextCount, long finalKnown, long previousFinal",
            "Return the observed increase between counters in consecutive observations. In the same generation, ignore downward movements. If the generation advances once, include all counts from the new generation and any remaining increments from previousCount to previousFinal when finalKnown is set. A known final count is at or above previousCount.",
            "if (nextCount >= previousCount) return nextCount - previousCount;\nif (nextGeneration == previousGeneration) return 0;\nreturn nextCount + (finalKnown == 1 ? previousFinal - previousCount : 0);",
            "if (nextGeneration == previousGeneration) return Math.Max(0, nextCount - previousCount);\nreturn nextCount + (finalKnown == 1 ? previousFinal - previousCount : 0);",
            [8, 8, 10, 14, 0, 0], 4, [8, 9, 10, 14, 1, 12], 16),
        Fault("ResolvePacketMode", "long declared, long inferred, long packetSchema, long inferredSchema, long supported",
            "Return the selected packet mode or -1. Mode codes run from 0 through 15. A declaration is authoritative even when its mode is unsupported, in which case return -1. When the declaration is -1, use an available inferred mode only in the same schema. Inferred is -1 when unavailable. The supported mask has one bit per mode.",
            "var candidate = declared > 0 ? declared : packetSchema == inferredSchema ? inferred : -1;\nreturn candidate >= 0 && (supported & (1L << (int)candidate)) != 0 ? candidate : -1;",
            "var candidate = declared >= 0 ? declared : packetSchema == inferredSchema ? inferred : -1;\nreturn candidate >= 0 && (supported & (1L << (int)candidate)) != 0 ? candidate : -1;",
            [3, 5, 2, 2, 40], 3, [0, 5, 2, 2, 33], 0),
        Fault("BucketPeak", "long first, long second, long firstAdjustment, long secondAdjustment, long present",
            "Report the maximum calibrated reading among present sensors, or -1 if neither is present. Present uses bit 0 for the first and bit 1 for the second. Each calibrated reading is its raw reading plus its own signed adjustment and is nonnegative when present.",
            "var firstPresent = (present & 1) != 0;\nvar secondPresent = (present & 2) != 0;\nif (firstPresent && (!secondPresent || first >= second)) return first + firstAdjustment;\nreturn secondPresent ? second + secondAdjustment : -1;",
            "var firstReading = (present & 1) != 0 ? first + firstAdjustment : -1;\nvar secondReading = (present & 2) != 0 ? second + secondAdjustment : -1;\nreturn Math.Max(firstReading, secondReading);",
            [10, 6, 2, 1, 3], 12, [10, 6, 0, 8, 3], 14),
        Fault("SamplePhase", "long tick, long clockShift, long period, long phase",
            "Return the smallest nonnegative delay until the corrected clock reaches the requested phase. Add the signed clockShift to tick before taking its phase in a cycle of positive length period. Requested phase lies from zero through period minus one.",
            "var shifted = (tick + clockShift) % period;\nreturn phase >= shifted ? phase - shifted : period + phase - shifted;",
            "var shifted = (tick + clockShift) % period;\nif (shifted < 0) shifted += period;\nreturn phase >= shifted ? phase - shifted : period + phase - shifted;",
            [9, 2, 8, 5], 2, [2, -5, 8, 6], 1),
        Fault("FlushCutoff", "long available, long spacing, long phase, long previous",
            "Choose the largest segment boundary at or before available, where boundaries start at phase and repeat at positive spacing. Preserve previous if this would move backward. Previous may be between boundaries after a format change, and available is at or above phase.",
            "var high = Math.Max(available, previous);\nreturn high - (high - phase) % spacing;",
            "var aligned = available - (available - phase) % spacing;\nreturn Math.Max(aligned, previous);",
            [102, 10, 3, 83], 93, [92, 10, 3, 91], 91),
        Fault("InterleavedTrackByte", "long frame, long track, long active",
            "Return the zero-based absolute byte offset of a track's sample, or -1 if the track is inactive. Each frame packs one byte per active track. Even frames store active tracks in ascending index order and odd frames store them in descending order. The 16-bit active mask uses bit positions 0 through 15 as track indexes.",
            "var bit = 1L << (int)track;\nif ((active & bit) == 0) return -1;\nvar width = System.Numerics.BitOperations.PopCount((ulong)active);\nvar ascending = System.Numerics.BitOperations.PopCount((ulong)(active & (bit - 1)));\nvar position = frame % 2 == 0 ? ascending : width - 1 - track;\nreturn frame * width + position;",
            "var bit = 1L << (int)track;\nif ((active & bit) == 0) return -1;\nvar width = System.Numerics.BitOperations.PopCount((ulong)active);\nvar ascending = System.Numerics.BitOperations.PopCount((ulong)(active & (bit - 1)));\nvar position = frame % 2 == 0 ? ascending : width - 1 - ascending;\nreturn frame * width + position;",
            [0, 2, 13], 1, [1, 2, 13], 4),
        Fault("BufferedCoverage", "long reader, long firstStart, long firstEnd, long secondStart, long secondEnd",
            "Return the first uncovered position at or above reader, considering the union of two buffered half-open intervals. Each interval is ordered. The first interval is the first to arrive and may start before or after the second interval.",
            "var reached = Extend(reader, firstStart, firstEnd);\nreturn Extend(reached, secondStart, secondEnd);\n\nstatic long Extend(long at, long start, long end) => start <= at && at < end ? end : at;",
            "var reached = Extend(reader, firstStart, firstEnd);\nreached = Extend(reached, secondStart, secondEnd);\nreturn Extend(reached, firstStart, firstEnd);\n\nstatic long Extend(long at, long start, long end) => start <= at && at < end ? end : at;",
            [4, 4, 9, 9, 12], 12, [4, 9, 12, 4, 9], 12),
        Fault("ExpandChannelState", "long transitions, long enabled, long beginsHigh",
            "Decode a 16-channel state word. Starting from the beginsHigh state before channel zero, each set bit in transitions toggles the state for its own channel and following channels until another toggle. Return the high bits for enabled channels. A disabled channel still participates in the wire encoding.",
            "var decoded = transitions & enabled;\ndecoded ^= decoded << 1;\ndecoded ^= decoded << 2;\ndecoded ^= decoded << 4;\ndecoded ^= decoded << 8;\nreturn (beginsHigh == 1 ? ~decoded : decoded) & enabled;",
            "var decoded = transitions;\ndecoded ^= decoded << 1;\ndecoded ^= decoded << 2;\ndecoded ^= decoded << 4;\ndecoded ^= decoded << 8;\nreturn (beginsHigh == 1 ? ~decoded : decoded) & enabled;",
            [5, 15, 0], 3, [1, 4, 0], 4),
        Fault("MergedRunRecords", "long firstRuns, long firstHead, long firstTail, long secondRuns, long secondHead, long secondTail",
            "The two chunks encode successive positions using one record per run of equal symbols. A chunk with no runs is empty and its symbols are immaterial. Return the number of run records for their concatenation plus one terminator if the result is nonempty. The chunks do not contain terminators.",
            "var runs = firstRuns + secondRuns;\nif (runs == 0) return 0;\nif (firstRuns > 0 && secondRuns > 0 && firstHead == secondTail) runs--;\nreturn runs + 1;",
            "var runs = firstRuns + secondRuns;\nif (runs == 0) return 0;\nif (firstRuns > 0 && secondRuns > 0 && firstTail == secondHead) runs--;\nreturn runs + 1;",
            [3, 9, 4, 2, 7, 8], 6, [3, 9, 4, 2, 4, 8], 5),
        Fault("RingSlot", "long sequence, long nextSequence, long capacity, long originSlot, long retainedStart",
            "Return the physical slot for the given sequence, or -1 if a sample is unavailable. A sample must precede nextSequence, fall within the last capacity sequence numbers, and be at or after the retainedStart watermark. Capacity is positive. The slot for sequence zero is originSlot, which is below capacity, and slot positions wrap thereafter.",
            "var hardwareStart = Math.Max(0, nextSequence - capacity);\nvar oldest = Math.Min(hardwareStart, retainedStart);\nif (sequence < oldest || sequence >= nextSequence) return -1;\nreturn (originSlot + sequence) % capacity;",
            "var hardwareStart = Math.Max(0, nextSequence - capacity);\nvar oldest = Math.Max(hardwareStart, retainedStart);\nif (sequence < oldest || sequence >= nextSequence) return -1;\nreturn (originSlot + sequence) % capacity;",
            [11, 15, 8, 2, 7], 5, [8, 15, 8, 2, 10], -1),
        Valid("ReferenceFrames", "long ticks, long ticksPerFrame, long maximum",
            "Return the number of complete reference frames represented by ticks, capped at maximum frames. TicksPerFrame is positive and a partial frame is excluded.",
            "return Math.Min(ticks / ticksPerFrame, maximum);", [31, 8, 4], 3),
        Valid("CompleteMeasure", "long first, long second, long firstPresent, long secondPresent",
            "Return the sum of two measurements only when both are present. Return -1 when either is absent. A zero measurement can still be present.",
            "return firstPresent == 1 && secondPresent == 1 ? first + second : -1;", [0, 8, 1, 1], 8)
    ]);
